def parse_duration(s: str) -> int:
    import re
    total = 0
    for value, unit in re.findall(r'(\d+)([hms])', s):
        value = int(value)
        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        elif unit == 's':
            total += value
    return total
