import re

def parse_duration(s: str) -> int:
    total = 0
    pattern = re.compile(r'(\d+)([hms])')
    for match in pattern.finditer(s):
        value = int(match.group(1))
        unit = match.group(2)
        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        elif unit == 's':
            total += value
    return total
```

